<script lang="ts">
 import{onMount}from'svelte';import EChartsRenderer from '../../charts/EChartsRenderer.svelte';import{v6ChartEpoch,v6CssVar}from'../v6ChartTheme';import{getV6IndexSeries,getV6RunDetail,getV6Reports,getV6Runs,type V6IndexSeries,type V6ReportEntry,type V6RunDetail,type V6Runs,type V6RunSeed}from'../v6Api';import{classifyType1State,isType1Identity}from'../type1Presentation';const CAPITAL=60000000;const VAL_START='2024-01-01';const VAL_END='2025-06-30';type ReportRecord=V6ReportEntry&Record<string,unknown>;let runsData=$state<V6Runs|null>(null);let reports=$state<readonly ReportRecord[]>([]);let detail=$state<V6RunDetail|null>(null);let selected=$state('');let error=$state<string|null>(null);let loading=$state(true);let detailLoading=$state(false);let kospi=$state<V6IndexSeries|null>(null);let kosdaq=$state<V6IndexSeries|null>(null);let indexBlocked=$state(false);let chartEpoch=$state('');v6ChartEpoch.subscribe((value)=>(chartEpoch=value));
 const key=(d:string|undefined,r:string|undefined)=>`${d??''}\u0000${r??''}`;const text=(v:unknown)=>v===undefined||v===null||v===''?'MISSING':String(v);const num=(v:unknown)=>typeof v==='number'&&Number.isFinite(v)?v:undefined;const won=(v:unknown)=>num(v)===undefined?'MISSING':`₩${new Intl.NumberFormat('ko-KR').format(num(v)!)}`;const color=v6CssVar;const shortSha=(v:string|undefined)=>v?`${v.slice(0,12)}…`:'MISSING';const seeds=()=>Object.entries(detail?.manifest?.per_seed??{}) as [string,V6RunSeed][];const rows=$derived([...seeds().map(([seed,v])=>({name:`policy seed ${seed}`,nav:num(v.final_val_metrics?.nav)})),...['no_trade','rule_topk_ret5','random_topk'].map(name=>({name,nav:num(detail?.manifest?.baselines?.[name]?.nav)}))].filter(x=>x.nav!==undefined));const chartOption=$derived.by(()=>{void chartEpoch;return{tooltip:{trigger:'axis',axisPointer:{type:'shadow'},valueFormatter:(v:number)=>won(v)},xAxis:{type:'value',axisLabel:{color:color('--muted'),formatter:(v:number)=>won(v)}},yAxis:{type:'category',data:rows.map(x=>x.name),axisLabel:{color:color('--muted')}},series:[{type:'bar',data:rows.map(x=>({value:x.nav,itemStyle:{color:x.nav!>=CAPITAL?color('--success'):x.nav!>=CAPITAL*.95?color('--muted'):color('--danger')}})),markLine:{silent:true,data:[{xAxis:CAPITAL,label:{formatter:'60M'}}]}}]}});
 type NormPoint={date:string;value:number};function normalized(series:V6IndexSeries|null):NormPoint[]{const all=series?.series??[];const windowed=all.filter(r=>r.date>=VAL_START&&r.date<=VAL_END);const rows=windowed.length>=2?windowed:all;if(!rows.length)return[];const base=rows[0].close;if(!(base>0))return[];return rows.map(r=>({date:r.date,value:r.close/base*100}))}
 const kospiNorm=$derived(normalized(kospi));const kosdaqNorm=$derived(normalized(kosdaq));const windowUsed=$derived((kospi?.series??[]).some(r=>r.date>=VAL_START&&r.date<=VAL_END));
 const seedMarks=$derived(seeds().map(([seed,v])=>({seed,pct:num(v.final_val_metrics?.nav)===undefined?undefined:num(v.final_val_metrics?.nav)!/CAPITAL*100})).filter(x=>x.pct!==undefined));
 const overlayOption=$derived.by(()=>{void chartEpoch;const dates=(kospiNorm.length>=kosdaqNorm.length?kospiNorm:kosdaqNorm).map(p=>p.date);return{tooltip:{trigger:'axis',valueFormatter:(v:number)=>`${v.toFixed(2)}`},legend:{textStyle:{color:color('--muted')}},grid:{left:56,right:24,top:36,bottom:46},xAxis:{type:'category',data:dates,axisLabel:{color:color('--muted')}},yAxis:{type:'value',scale:true,axisLabel:{color:color('--muted'),formatter:(v:number)=>v.toFixed(0)}},dataZoom:[{type:'inside'},{type:'slider',height:18}],series:[{name:'KOSPI (기준=100)',type:'line',showSymbol:false,data:kospiNorm.map(p=>[p.date,p.value]),lineStyle:{width:2}},{name:'KOSDAQ (기준=100)',type:'line',showSymbol:false,data:kosdaqNorm.map(p=>[p.date,p.value]),lineStyle:{width:2}},{name:'정책 최종 val NAV 수준',type:'line',data:[],markLine:{silent:true,symbol:'none',data:seedMarks.map(m=>({yAxis:m.pct,label:{formatter:`seed ${m.seed} · ${m.pct!.toFixed(1)}`,color:color('--warn')},lineStyle:{type:'dashed',color:color('--warn')}}))}}]}});
 async function selectRun(){const[d,r]=selected.split('\u0000');if(!d||!r)return;detailLoading=true;detail=null;const x=await getV6RunDetail(d,r);detailLoading=false;if(x.ok&&x.data)detail=x.data;else error=x.error??'알 수 없는 오류가 발생했습니다.'}const reportText=(report:ReportRecord,key:string)=>text(report[key]);const reportFamily=(report:ReportRecord)=>text(report.family??report.report_family);const reportAvailability=(report:ReportRecord)=>classifyType1State(report)??reportText(report,'availability');const type1Reports=$derived(reports.filter(isType1Identity));const m3eReports=$derived(reports.filter(report=>reportFamily(report)==='M3E'));const otherReports=$derived(reports.filter(report=>!isType1Identity(report)&&reportFamily(report)!=='M3E'));async function load(){const[runsResult,reportsResult,kospiResult,kosdaqResult]=await Promise.all([getV6Runs(),getV6Reports(),getV6IndexSeries('KOSPI'),getV6IndexSeries('KOSDAQ')]);loading=false;if(reportsResult.ok&&reportsResult.data)reports=(reportsResult.data.reports??[]) as readonly ReportRecord[];if(kospiResult.ok&&kospiResult.data?.status==='OK')kospi=kospiResult.data;if(kosdaqResult.ok&&kosdaqResult.data?.status==='OK')kosdaq=kosdaqResult.data;indexBlocked=!(kospiResult.ok&&kospiResult.data?.status==='OK')||!(kosdaqResult.ok&&kosdaqResult.data?.status==='OK');if(runsResult.ok&&runsResult.data){runsData=runsResult.data;const run=runsResult.data.runs?.[0];if(run){selected=key(run.dataset_run_id,run.run_id);selectRun()}}else error=runsResult.error??'알 수 없는 오류가 발생했습니다.'}onMount(load);
</script>
{#if loading}<section class="panel" aria-live="polite">비교할 실행 기록을 확인하고 있습니다.</section>{:else if error&&!runsData}<section class="panel error" role="alert">{error}</section>{:else if runsData}<section class="compare-page"><header><p class="eyebrow">RESEARCH COMPARISON</p><h1>비교</h1><p>동일한 공개 validation 증거만 같은 lane 안에서 읽습니다. 서로 다른 가족·구간·상태의 artifact는 순위를 매기지 않습니다.</p></header><section class="card wide comparison-lanes" aria-labelledby="comparison-lanes-title"><h2 id="comparison-lanes-title">증거 호환성 lane</h2><p class="note">Type1은 순차적 MaskablePPO(15:20 proxy, 23bp, 60M fixed-notional, max 10)이며 fresh OOS는 NOT_RUN입니다. V8 M3E는 LinUCB contextual-bandit NO_GO로, Type1 정책 또는 수익 비교 대상이 아닙니다.</p><div class="lane-grid"><article><h3>Type1 · sequential MaskablePPO</h3>{#each type1Reports as report}<p><b>{reportAvailability(report)}</b> · {reportText(report,'compatibility_state')} · {reportText(report,'availability')} · revisions {(report.revisions??report.reports??[]).length}</p>{:else}<p>UNAVAILABLE · 공개 validation artifact 없음</p>{/each}</article><article><h3>V8 M3E · LinUCB contextual-bandit</h3>{#each m3eReports as report}<p><b>NO_GO</b> · {reportText(report,'availability')} · {reportText(report,'test_state')} · Type1과 INELIGIBLE</p>{:else}<p>UNAVAILABLE · M3E 공개 artifact 없음</p>{/each}</article><article><h3>Rule baselines / controls</h3><p>선택한 동일 manifest 안의 no-trade, equal-weight/momentum 또는 rule baseline만 표시합니다. 다른 artifact와 cross-rank하지 않습니다.</p><p>Shuffled-label controls: NOT_RUN 또는 UNAVAILABLE; synthetic evidence를 정책 증거로 재명명하지 않습니다.</p></article></div>{#if otherReports.length}<p class="ineligible">다른 family 또는 legacy artifact {otherReports.length}건: INELIGIBLE · 공개 validation 호환성이 확인되지 않아 순위에서 제외.</p>{/if}</section>{#if !(runsData.runs?.length)}<section class="empty-state"><h2>비교할 실행이 없습니다</h2></section>{:else}<section class="card picker"><h2>실행 선택</h2>{#each runsData.runs??[] as run}<button class:chosen={selected===key(run.dataset_run_id,run.run_id)} onclick={()=>{selected=key(run.dataset_run_id,run.run_id);selectRun()}}>{text(run.dataset_run_id)} · {text(run.run_id)}</button>{/each}</section>{#if detailLoading}<section class="card">선택한 실행 manifest를 읽고 있습니다.</section>{:else if detail?.manifest}<section class="card wide"><h2>동일 manifest 내 validation NAV</h2>{#if rows.length}<EChartsRenderer option={chartOption} height="320px" caption="동일 manifest 전략별 validation NAV · 60M 기준선" />{:else}<p>표시할 데이터 없음 · NOT_RUN</p>{/if}</section><section class="card wide"><h2>동일 manifest 수치 매트릭스</h2><div class="table-wrap"><table><thead><tr><th>지표</th>{#each seeds() as [seed]}<th>policy seed {seed}</th>{/each}<th>no_trade</th><th>rule_topk_ret5</th><th>random_topk</th></tr></thead><tbody><tr><th>val NAV</th>{#each seeds() as [,v]}<td>{won(v.final_val_metrics?.nav)}</td>{/each}{#each ['no_trade','rule_topk_ret5','random_topk'] as name}<td>{won(detail.manifest.baselines?.[name]?.nav)}</td>{/each}</tr></tbody></table></div></section>{#if indexBlocked}<div class="grid"><section class="card blocked"><h2>KOSPI / KOSDAQ</h2><p>BLOCKED_INDEX_SERIES_SOURCE · KRX 자격증명 필요</p></section><section class="card"><h2>변형 검증</h2><p>H3 / H5 · NOT_RUN · 변형 검증 대기</p></section></div>{:else}<section class="card wide"><h2>KOSPI / KOSDAQ 대비 <span class="chip ok">PRESENT · pykrx offline artifact</span></h2><p class="note">{windowUsed?`검증 구간 ${VAL_START} ~ ${VAL_END} 기준=100 정규화 지수 곡선입니다.`:'검증 구간 밖 artifact라 전체 수집 구간을 기준=100으로 표시합니다.'} 수평 점선은 정책 seed의 최종 validation NAV 수준(60M=100)입니다. 지수는 레벨 관측용이며 매매·수익 근거가 아닙니다.</p>{#if kospiNorm.length||kosdaqNorm.length}<EChartsRenderer option={overlayOption} height="360px" caption="지수 정규화(기준=100) · 정책 최종 val NAV 수평선" />{:else}<p>표시할 지수 데이터 없음</p>{/if}<div class="prov">{#each [kospi,kosdaq] as s}{#if s}<dl><dt>{s.market}</dt><dd>{text(s.actual_start_date)} ~ {text(s.actual_end_date)} · {s.row_count ?? 'MISSING'} rows · pykrx {text(s.provider_package?.version)} · SHA {shortSha(s.hashes?.normalized_sha256)} · 결측일 비보간</dd></dl>{/if}{/each}</div></section><div class="grid"><section class="card"><h2>변형 검증</h2><p>H3 / H5 · NOT_RUN · 변형 검증 대기</p></section></div>{/if}{/if}{/if}</section>{/if}
<style>.compare-page,.panel{width:100%;border:1px solid var(--border);border-radius:14px;padding:clamp(18px,4vw,32px);background:var(--surface);color:var(--fg)}.grid,.lane-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,280px),1fr));gap:16px;margin-top:16px}.card,.empty-state{margin-top:16px;border:1px solid var(--border-strong);border-radius:10px;padding:16px;background:var(--surface-raised)}.wide{grid-column:1/-1}.eyebrow{color:var(--accent);font-size:.82rem;font-weight:800;letter-spacing:.1em}h1,h2,h3{color:var(--fg-strong)}h1{font-size:clamp(1.8rem,6vw,2.6rem)}h2{font-size:1.15rem}.lane-grid article{min-width:0;border:1px solid var(--border);border-radius:8px;padding:12px;background:var(--surface-sunken)}.lane-grid p,.ineligible{overflow-wrap:anywhere}.ineligible{color:var(--warn)}.picker button{display:block;width:100%;margin:6px 0;border:1px solid var(--border-strong);border-radius:6px;padding:8px;background:var(--surface-sunken);color:var(--fg);font:inherit;text-align:left}.picker .chosen{border-color:var(--accent)}.blocked{border-color:var(--danger);background:var(--danger-soft);color:var(--danger)}.chip{display:inline-block;border:1px solid currentColor;border-radius:999px;margin-left:8px;padding:2px 8px;font-size:.72rem;font-weight:800;vertical-align:middle}.chip.ok{color:var(--success)}.note{color:var(--muted);font-size:.92rem}.prov{margin-top:10px;border-top:1px solid var(--border);padding-top:10px}.prov dl{display:grid;grid-template-columns:auto 1fr;gap:6px 14px;margin:4px 0;font-size:.85rem}.prov dt{color:var(--muted);font-weight:800}.prov dd{margin:0;overflow-wrap:anywhere}.table-wrap{overflow-x:auto}table{width:100%;min-width:720px;border-collapse:collapse;font-size:.85rem}th,td{border-top:1px solid var(--border);padding:8px;text-align:left}th{color:var(--muted)}.error{color:var(--danger)}</style>
